currentprojection = perspective(6,3,2);

triple I = (1,0,0), J = (0,1,0), K = (0,0,1);
triple O = (0,-0.5,0);

draw(surface((2*I + 2*J)--(2*I)--(2*I + 2*K)--cycle),paleyellow,nolight);
draw(surface((2*I + 2*K)--(2*K)--(2*J + 2*K)--cycle),paleyellow,nolight);
draw(surface((2*J + 2*K)--(2*J)--(2*I + 2*J)--cycle),paleyellow,nolight);
draw((2*I + 2*J)--(2*I)--(2*I + 2*K)--cycle);
draw((2*I + 2*K)--(2*K)--(2*J + 2*K)--cycle);
draw((2*J + 2*K)--(2*J)--(2*I + 2*J)--cycle);
draw((O + 0.2*(2*I))--(O + 0.2*(2*I) + 0.1*(2*J))--(O + 0.1*(2*J)));
draw((O + 0.2*(2*J))--(O + 0.2*(2*J) + 0.1*(2*K))--(O + 0.1*(2*K)));
draw((O + 0.2*(2*K))--(O + 0.2*(2*K) + 0.1*(2*I))--(O + 0.1*(2*I)));
